import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Kimi chat and Agent cookbook","description":"You can already open kimi.com. One recipe per job: goal, official entry, steps, pitfall.","frontmatter":{"title":"Kimi chat and Agent cookbook","description":"You can already open kimi.com. One recipe per job: goal, official entry, steps, pitfall.","domain":"product","tags":["chat"],"role":"cookbook"},"headers":[],"relativePath":"products/kimi/kimi-cookbook.md","filePath":"products/kimi/kimi-cookbook.md","lastUpdated":1787107158000}'),i={name:"products/kimi/kimi-cookbook.md"};function l(n,e,s,c,p,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="kimi-chat-and-agent-cookbook" tabindex="-1">Kimi chat and Agent cookbook <a class="header-anchor" href="#kimi-chat-and-agent-cookbook" aria-label="Permalink to &quot;Kimi chat and Agent cookbook&quot;">​</a></h1><p>You can already open <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>. One recipe per job. Kimi Code install is not here — see <a href="/products/kimi-code/">Kimi Code</a>.</p><h2 id="_1-get-a-downloadable-agent-deliverable" tabindex="-1">1. Get a downloadable Agent deliverable <a class="header-anchor" href="#_1-get-a-downloadable-agent-deliverable" aria-label="Permalink to &quot;1. Get a downloadable Agent deliverable&quot;">​</a></h2><p><strong>Goal:</strong> a site, deck, sheet, or report — not a chat paragraph.</p><p><strong>Entry:</strong> <a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a>; app model switch → <strong>K3</strong> (<a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a>).</p><ol><li>Use a task-shaped prompt (official style: build voting-site code).</li><li>Let planning / tools / delivery finish.</li><li>Download the project or Office file, or open the deploy link.</li></ol><p><strong>Pitfall:</strong> this Agent does not edit a git checkout on disk.</p><h2 id="_2-use-swarm-for-large-collection" tabindex="-1">2. Use Swarm for large collection <a class="header-anchor" href="#_2-use-swarm-for-large-collection" aria-label="Permalink to &quot;2. Use Swarm for large collection&quot;">​</a></h2><p><strong>Goal:</strong> hundreds of sources, multi-perspective review, or a very long document.</p><p><strong>Entry:</strong> <a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a>; app → <strong>K3 Swarm</strong> (<a href="https://www.kimi.com/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a>).</p><p>Official examples you can adapt:</p><ul><li>collect 200+ Paul Graham essays</li><li>top 3 creators in 100 YouTube niches</li><li>a 100-page literature review from 40 PDFs</li></ul><p><strong>Pitfall:</strong> Moderato and above only; burns more credits than standard Agent; <strong>[Beta]</strong> may be limited.</p><h2 id="_3-create-a-project-for-long-running-work" tabindex="-1">3. Create a Project for long-running work <a class="header-anchor" href="#_3-create-a-project-for-long-running-work" aria-label="Permalink to &quot;3. Create a Project for long-running work&quot;">​</a></h2><p><strong>Goal:</strong> the same style guide / PDF set across many turns.</p><p><strong>Entry:</strong> <strong>+</strong> next to Projects, or <strong>+ New project</strong> (<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>).</p><ol><li>Name 1–50 characters; optional instructions (official example: &quot;You are a senior product manager. Reply in Chinese and output in Markdown.&quot;).</li><li>Upload files: ≤ 100 MB each, up to 50.</li><li>Start a separate in-project chat per distinct output.</li><li>Project chats can use plugins, Skills, and Goal, and can switch models.</li></ol><p><strong>Pitfall:</strong> delete is permanent. Kimi Work Projects <strong>do not</strong> share this data.</p><h2 id="_4-schedule-a-daily-job" tabindex="-1">4. Schedule a daily job <a class="header-anchor" href="#_4-schedule-a-daily-job" aria-label="Permalink to &quot;4. Schedule a daily job&quot;">​</a></h2><p><strong>Goal:</strong> a briefing that runs without you clicking.</p><p><strong>Entry:</strong> sidebar <strong>Create scheduled task</strong>, or natural language in chat (<a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a>).</p><p>Official copy-paste prompt:</p><blockquote><p>Every day at 9:00, summarize the latest market news as 3 key points plus 1 risk note, in Chinese, within 200 words.</p></blockquote><ol><li>Dry-run in a normal chat or use &quot;Run once now&quot;.</li><li>If it depends on a Skill, install and test the Skill first.</li><li>Tasks created on kimi.com run in the cloud; the client need not stay open.</li></ol><p><strong>Pitfall:</strong> default expiry Daily +7 days, Weekly +1 month, Monthly +3 months. Local Kimi Work tasks do not backfill while the app is closed. Over the active cap, new tasks save as inactive.</p><h2 id="_5-pin-an-output-format-with-a-skill" tabindex="-1">5. Pin an output format with a Skill <a class="header-anchor" href="#_5-pin-an-output-format-with-a-skill" aria-label="Permalink to &quot;5. Pin an output format with a Skill&quot;">​</a></h2><p><strong>Goal:</strong> weekly reports / SOPs / research structure without re-explaining.</p><p><strong>Entry:</strong> <a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">What are Skills?</a></p><ol><li>Browse official / recommended skills; click <strong>+</strong>.</li><li>Type <code>/</code> to invoke, or let Kimi trigger.</li><li>Missing skill: upload a document, or <code>/skill-creator</code>.</li></ol><p>Official names: <code>docx</code>, <code>deep-research</code>; recommended <code>sop-writer</code>, <code>event-etf-study</code>.</p><p><strong>Pitfall:</strong> skills load only when relevant. Creating a skill consumes credits (Creating skills FAQ).</p><h2 id="_6-attach-plugins-to-agent" tabindex="-1">6. Attach plugins to Agent <a class="header-anchor" href="#_6-attach-plugins-to-agent" aria-label="Permalink to &quot;6. Attach plugins to Agent&quot;">​</a></h2><p><strong>Goal:</strong> company registry / GitHub / Notion instead of search-only.</p><p><strong>Entry:</strong> sidebar <strong>Plugins</strong>, or <strong>+</strong> / <code>/</code> (<a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a>).</p><ol><li>Switch the model to <strong>K3</strong> or <strong>K3 Swarm</strong> (Deep Research / Websites / PPT also work).</li><li>Sign in, install, complete OAuth if asked.</li><li>You can invoke multiple plugins at once.</li></ol><p><strong>Pitfall:</strong> not supported in Claw or Kimi Plus chats. Signed-out users cannot install. Catalog varies by region and enterprise. Some plugins bill membership credits.</p><h2 id="_7-one-click-deploy-a-claw" tabindex="-1">7. One-click deploy a Claw <a class="header-anchor" href="#_7-one-click-deploy-a-claw" aria-label="Permalink to &quot;7. One-click deploy a Claw&quot;">​</a></h2><p><strong>Goal:</strong> a 24/7 cloud assistant on Feishu / WeCom without buying a server.</p><p><strong>Entry:</strong> <a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a> (<a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a>).</p><ol><li>Confirm <strong>Allegretto or higher</strong>.</li><li><strong>Create</strong> Kimi Claw and wait.</li><li><strong>Settings → Chat channels</strong>.</li></ol><p>Existing OpenClaw: <strong>Link existing OpenClaw</strong>, install the Kimi plugin on that host.</p><p><strong>Pitfall:</strong> default model is <strong>K2.6</strong>, billed to membership credits. Switching to K3 edits OpenClaw config, not a web slash command.</p><h2 id="_8-start-a-claw-group-chat" tabindex="-1">8. Start a Claw group chat <a class="header-anchor" href="#_8-start-a-claw-group-chat" aria-label="Permalink to &quot;8. Start a Claw group chat&quot;">​</a></h2><p><strong>Goal:</strong> several Claws under Kimi Conductor.</p><p><strong>Entry:</strong> Claw sidebar <strong>+</strong> → <strong>Start Group Chat</strong> (<a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a>).</p><ol><li>Required <strong>Group Name</strong> and <strong>Group Goal</strong>.</li><li>Select linked Claws, Create.</li><li>Set group rules in natural language.</li><li>Preview files in <strong>Workspace</strong>.</li><li>A Claw that will not stop: send <strong><code>/stop</code></strong> in the main chat.</li></ol><p><strong>Pitfall:</strong> group chat is Allegretto+, 10 groups on the membership table. If @-mention is silent, check the Claw&#39;s private chat first. Third-party OpenClaw version bounds are on the group-chat help page.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./kimi.html">Tutorial</a></li><li><a href="./kimi-cheatsheet.html">Cheatsheet</a></li><li><a href="./kimi-glossary.html">Glossary</a></li></ul>',49)])])}const f=t(i,[["render",l]]);export{k as __pageData,f as default};
